import java.io.*;
import java.util.*;

public class E {
    static class Reader {
        BufferedReader br;
        StringTokenizer st;

        public Reader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        String nextLine() {
            String line = "";
            try {
                line = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return line;
        }
    }

    static Reader r = new Reader();
    static PrintWriter pw = new PrintWriter(System.out);

    private static int[] readIntArray(int size) {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = r.nextInt();
        }
        return arr;
    }

    private static long[] readLongArray(int size) {
        long[] arr = new long[size];
        for (int i = 0; i < size; i++) {
            arr[i] = r.nextLong();
        }
        return arr;
    }

    private static int getNextInt() {
        return r.nextInt();
    }

    private static long getNextLong() {
        return r.nextLong();
    }

    private static String getNextString() {
        return r.nextToken();
    }

    static int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    static int binarySearch(List<Long> list, long val, int start) {
        int left = start, right = list.size() - 1;
        int res = list.size();

        while (left <= right) {
            int mid = (left + right) / 2;
            if (list.get(mid) > val) {
                if (mid == 0) return mid;
                if (list.get(mid - 1) <= val) return mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return res;
    }

    static long solve(List<Node> nodes, long[] b, int index) {
        if (index == 3) return 0;

        Node node = nodes.get(index);
        int bIdx = node.ind - 1;
        if (bIdx == -1) bIdx = 2;

        long minA = Math.min(node.val, b[bIdx]);
        node.val -= minA;
        b[bIdx] -= minA;

        long minB = Math.min(node.val, b[node.ind]);
        node.val -= minB;
        b[node.ind] -= minB;

        long res1 = node.val + solve(nodes, b, index + 1);
        node.val += minA + minB;
        b[bIdx] += minA;
        b[node.ind] += minB;

        // second scenario
        node = nodes.get(index);
        bIdx = node.ind - 1;
        if (bIdx == -1) bIdx = 2;

        long minC = Math.min(node.val, b[node.ind]);
        node.val -= minC;
        b[node.ind] -= minC;

        long minD = Math.min(node.val, b[bIdx]);
        node.val -= minD;
        b[bIdx] -= minD;

        long res2 = node.val + solve(nodes, b, index + 1);
        node.val += minC + minD;
        b[bIdx] += minD;
        b[node.ind] += minC;

        return Math.min(res1, res2);
    }

    public static void main(String[] args) {
        StringBuilder output = new StringBuilder();
        int t = 1;
        while (t-- > 0) {
            int n = getNextInt();
            long[] a = readLongArray(3);
            long[] b = readLongArray(3);

            long maxVal = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            long minVal = Math.max(0, a[0] + b[1] - n) + Math.max(0, a[1] + b[2] - n) + Math.max(0, a[2] + b[0] - n);
            output.append(minVal).append(" ").append(maxVal).append("\n");
        }
        pw.print(output.toString());
        pw.flush();
    }

    static class Node {
        int ind;
        long val;

        public Node(int ind, long val) {
            this.ind = ind;
            this.val = val;
        }
    }
}
